"use client";
import React, { useEffect, useState } from "react";
import DocumentUpload from "@/components/document-upload";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import dynamic from "next/dynamic";

const PDFDocument = dynamic(
  () => import("react-pdf").then(mod => mod.Document),
  { ssr: false }
);
const PDFPage = dynamic(
  () => import("react-pdf").then(mod => mod.Page),
  { ssr: false }
);

function DriveFileCard({ doc, onPreview }: { doc: string; onPreview: (doc: string) => void }) {
  return (
    <div className="flex flex-col items-center bg-white rounded-lg border shadow p-4 w-40 h-40 relative group hover:shadow-lg transition-shadow">
      <img src="/file.svg" alt="File" className="w-10 h-10 mb-2 mt-2" />
      <div className="text-xs font-medium text-gray-800 text-center truncate w-full" title={doc}>
        {doc}
      </div>
      <div className="flex flex-row gap-2 mt-auto">
        <button
          className="text-blue-600 underline text-xs opacity-100 hover:opacity-100 transition-opacity"
          onClick={() => onPreview(doc)}
          type="button"
        >
          Preview
        </button>
        <a
          href={`http://localhost:8000/docs/${encodeURIComponent(doc)}`}
          target="_blank"
          rel="noopener noreferrer"
          className="text-blue-600 underline text-xs opacity-100 hover:opacity-100 transition-opacity"
        >
          Download
        </a>
      </div>
    </div>
  );
}

function PreviewModal({ doc, onClose }: { doc: string; onClose: () => void }) {
  const [error, setError] = useState<string | null>(null);
  useEffect(() => { setError(null); }, [doc]);
  if (!doc) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-40">
      <div className="bg-white rounded-lg shadow-lg p-4 max-w-2xl w-full relative">
        <button
          className="absolute top-2 right-2 text-gray-500 hover:text-gray-800 text-lg"
          onClick={onClose}
          aria-label="Close preview"
        >
          ×
        </button>
        <div className="h-[70vh] overflow-auto flex flex-col items-center justify-center">
          <PDFDocument
            file={`http://localhost:8000/docs/${encodeURIComponent(doc)}`}
            onLoadError={() => setError("Failed to load PDF")}
            loading={<div>Loading PDF...</div>}
            error={<div className="text-red-600">{error || "Failed to load PDF."}</div>}
          >
            <PDFPage pageNumber={1} width={500} />
          </PDFDocument>
        </div>
      </div>
    </div>
  );
}

export default function DocumentsPage() {
  const [documents, setDocuments] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [previewDoc, setPreviewDoc] = useState<string | null>(null);

  const fetchDocuments = async () => {
    setLoading(true);
    setError(null);
    try {
      // Call FastAPI backend directly (adjust URL as needed)
      const response = await fetch("http://localhost:8000/upload", {
        method: "GET",
      });
      const data = await response.json();
      if (!response.ok) {
        setError(data.error || "Failed to fetch documents.");
        setDocuments([]);
      } else {
        setDocuments(data.documents || []);
      }
    } catch {
      setError("Network or server error.");
      setDocuments([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDocuments();
    // Only runs on client
    import("react-pdf").then(({ pdfjs }) => {
      pdfjs.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjs.version}/pdf.worker.min.js`;
    });
  }, []);

  return (
    <div className="max-w-2xl mx-auto py-8 space-y-8 bg-[#FAFAF6]">
      <Card className="bg-white">
        <CardHeader>
          <CardTitle>Upload New Document</CardTitle>
        </CardHeader>
        <CardContent>
          <DocumentUpload onUpload={fetchDocuments} />
        </CardContent>
      </Card>

      <Card className="bg-white">
        <CardHeader>
          <CardTitle>Already Uploaded Documents</CardTitle>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div>Loading...</div>
          ) : error ? (
            <div className="text-red-600">{error}</div>
          ) : documents.length === 0 ? (
            <div>No documents uploaded yet.</div>
          ) : (
            <ScrollArea className="h-80 w-full">
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-6 p-2">
                {documents.map((doc) => (
                  <DriveFileCard key={doc} doc={doc} onPreview={setPreviewDoc} />
                ))}
              </div>
            </ScrollArea>
          )}
        </CardContent>
      </Card>
      {previewDoc && (
        <PreviewModal doc={previewDoc} onClose={() => setPreviewDoc(null)} />
      )}
    </div>
  );
} 